package com.dating.social.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * @param idempotencyKey generated by the client once per super like attempt and reused on retries,
 *                       so a retry never spends a second super like
 */
public record SuperlikeRequest(
        @NotBlank(message = "Укажите idempotencyKey")
        @Size(max = 100, message = "idempotencyKey не должен превышать 100 символов")
        String idempotencyKey
) {
}
